/// Python's result against the port's, allowing for what the two representations cannot share:
/// a set's order, a truthy object read as a bool, and None read as "" for a str contract.
fn same(py: &Json, rs: &Json) -> bool {
    if py == rs {
        return true;
    }
    match (py, rs) {
        (_, Json::Bool(b)) if !py.is_boolean() => truthy(py) == *b,
        (Json::Null, Json::String(s)) => s.is_empty(),
        (Json::Array(x), Json::Object(r)) if r.contains_key("__set__") => {
            let key = |v: &Json| serde_json::to_string(v).unwrap();
            let mut a: Vec<String> = x.iter().map(key).collect();
            let mut b: Vec<String> = r["__set__"].as_array().map(|v| v.iter().map(key).collect()).unwrap_or_default();
            a.sort();
            b.sort();
            a == b
        }
        // Python's `(None, None)` (or `(None, None, None)`) for "nothing", an Option's None here
        (Json::Array(x), Json::Null) => !x.is_empty() && x.iter().all(Json::is_null),
        // Python's `{}` for "no turn"
        (Json::Object(o), Json::Null) => o.is_empty(),
        (Json::Object(o), Json::Object(r)) if r.contains_key("__turn__") => {
            ["user", "bot"].iter().all(|k| o.get(*k).and_then(Json::as_str).unwrap_or("") == r[*k].as_str().unwrap_or(""))
                && o.get("module").cloned().unwrap_or(Json::Null) == r["module"]
        }
        // Python's `()` read as "nothing" where the port's contract is a str
        (Json::Array(x), Json::String(s)) => x.is_empty() && s.is_empty(),
        _ => false,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let only = args.iter().position(|a| a == "--fn").map(|i| args[i + 1].clone());
    let show: usize = args.iter().position(|a| a == "--show").map(|i| args[i + 1].parse().unwrap()).unwrap_or(3);
    if std::env::var_os("RSBOT_TODAY").is_none() {
        eprintln!("set RSBOT_TODAY=2026-11-17 (the day every recording was made)");
        std::process::exit(2);
    }
    let mut objs: HashMap<String, Json> = HashMap::new();
    for line in std::io::BufReader::new(std::fs::File::open(format!("{dir}/objs.jsonl")).unwrap()).lines() {
        let r: Json = serde_json::from_str(&line.unwrap()).unwrap();
        objs.insert(r["h"].as_str().unwrap().to_string(), r["v"].clone());
    }
    std::panic::set_hook(Box::new(|_| {}));
    let mut tally: BTreeMap<String, [usize; 5]> = BTreeMap::new(); // ok, wrong, unported, panic, skipped
    let mut shown: HashMap<String, usize> = HashMap::new();
    let mut deps: BTreeMap<String, usize> = BTreeMap::new(); // the stub a call stopped at
    for line in std::io::BufReader::new(std::fs::File::open(format!("{dir}/calls.jsonl")).unwrap()).lines() {
        let r: Json = serde_json::from_str(&line.unwrap()).unwrap();
        let name = r["fn"].as_str().unwrap().to_string();
        if only.as_ref().is_some_and(|o| !name.ends_with(&format!(":{o}")) && *o != name && !name.starts_with(&format!("{o}:"))) {
            continue;
        }
        if !r["raised"].is_null() {
            continue;
        }
        let a: Vec<Json> = r["args"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| match x.get("$ref").and_then(Json::as_str) { Some(h) => objs[h].clone(), None => x.clone() })
            .collect();
        let t = tally.entry(name.clone()).or_default();
        let got = std::panic::catch_unwind(|| call(&name, &a));
        match got {
            Ok(None) => t[4] += 1,
            Ok(Some(rs)) => {
                if same(&r["result"], &rs) {
                    t[0] += 1;
                } else {
                    t[1] += 1;
                    let n = shown.entry(name.clone()).or_default();
                    if *n < show {
                        *n += 1;
                        let mut args_s = serde_json::to_string(&r["args"]).unwrap();
                        if args_s.len() > 400 { args_s.truncate(400); }
                        println!("WRONG {name}\n  args {args_s}\n  py   {}\n  rs   {}", r["result"], rs);
                    }
                }
            }
            Err(e) => {
                let msg = e.downcast_ref::<String>().cloned().or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default();
                if msg.starts_with("UNPORTED") {
                    t[2] += 1;
                    *deps.entry(msg.clone()).or_default() += 1;
                } else {
                    t[3] += 1;
                    let n = shown.entry(name.clone()).or_default();
                    if *n < show {
                        *n += 1;
                        println!("PANIC {name}: {msg}");
                    }
                }
            }
        }
    }
    let mut sum = [0usize; 5];
    for (name, t) in &tally {
        for i in 0..5 { sum[i] += t[i]; }
        if t[1] + t[3] > 0 || only.is_some() {
            println!("{name}: ok {} wrong {} unported {} panic {} skipped {}", t[0], t[1], t[2], t[3], t[4]);
        }
    }
    if args.iter().any(|a| a == "--deps") {
        let mut d: Vec<_> = deps.iter().collect();
        d.sort_by(|a, b| b.1.cmp(a.1));
        for (m, n) in d { println!("{n:6} {m}"); }
    }
    println!("TOTAL: ok {} wrong {} unported {} panic {} skipped {} ({} functions)", sum[0], sum[1], sum[2], sum[3], sum[4], tally.len());
}
